-- MN: 116 researched stops.
--
-- 113 new, 3 updating a row already in the index.
-- After running this and scripts/refresh-site.mts, /explore should read
-- 7121.
--
-- Coordinates are deliberately NOT updated on conflict: a checked position
-- must never be replaced by an unchecked one. Where the existing row came
-- from the OpenStreetMap scan and is wrong by a kilometre, delete that slug
-- first and let this insert instead.
--
-- state is deliberately NOT updated either. That is how an overwritten stop
-- in another state keeps its old state and hides — so the collision check
-- above refuses rather than relying on anyone noticing afterwards.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, timezone)
values
  ('Big Ole', 'big-ole', 'roadside-oddities', 45.89106, -95.37729, 'Alexandria', 'MN', 'A 28-foot Viking towers over Alexandria''s waterfront, a surviving piece of Minnesota''s 1965 New York World''s Fair promotion. The deliberately oversized warrior became the city''s enduring symbol and a classic lake-country photo stop.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Akeley Giant Paul Bunyan', 'akeley-giant-paul-bunyan', 'folklore', 47.00278, -94.73833, 'Akeley', 'MN', 'A kneeling Paul Bunyan stretches a huge hand toward visitors in downtown Akeley. Unlike many upright Bunyan statues, this one was designed so travelers can climb into the open palm for a deliberately theatrical photo.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Paul Bunyan''s Grave', 'paul-bunyans-grave', 'folklore', 47.93955, -94.44755, 'Kelliher', 'MN', 'Kelliher leans into the Paul Bunyan legend with a giant grave mound and marker claiming the mythical lumberjack is buried here. The joke is presented as civic folklore rather than history, making it an unusually literal monument to a fictional person.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Paul Bunyan Land', 'paul-bunyan-land', 'roadside-oddities', 46.35134, -94.02935, 'Brainerd', 'MN', 'A giant talking Paul Bunyan has greeted generations of visitors at this old-school amusement park, with an equally enormous Babe nearby. The attraction preserves a distinctly mid-century form of Minnesota roadside tourism around rides, statues and folklore.', 'limited', 'https://paulbunyanland.com/', 'America/Chicago'),
  ('Jolly Green Giant', 'jolly-green-giant', 'roadside-oddities', 43.65129, -94.0951, 'Blue Earth', 'MN', 'The 55-foot Jolly Green Giant stands in a public park as an enormous reminder of southern Minnesota''s connection to the Green Giant brand. Travelers can walk directly to the pedestal rather than viewing the advertising icon from a highway shoulder.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Ball of Twine Made by One Man', 'world-s-largest-ball-of-twine-made-by-one-man', 'roadside-oddities', 45.09633, -94.41027, 'Darwin', 'MN', 'Francis A. Johnson spent decades winding sisal twine into a 17,400-pound ball, turning obsessive repetition into a famous roadside landmark. The ball is protected inside a glass gazebo, so it remains visible even when the adjacent museum is closed.', 'roadside', 'https://www.darwintwineball.com/twineball.html', 'America/Chicago'),
  ('World''s Largest Tiger Muskie', 'world-s-largest-tiger-muskie', 'roadside-oddities', 46.96446, -94.8422, 'Nevis', 'MN', 'Nevis has celebrated its lake country with a giant tiger muskie since 1949. The oversized fish sits in a public setting near the Heartland Trail and gives the tiny community one of Minnesota''s oldest giant-fish landmarks.', 'open', 'https://cityofnevismn.gov/', 'America/Chicago'),
  ('Otto the Otter', 'otto-the-otter', 'roadside-oddities', 46.27695, -96.06136, 'Fergus Falls', 'MN', 'A huge concrete otter rises beside Grotto Lake in Fergus Falls, built as a community project in the 1970s. Otto turns a familiar Minnesota animal into a civic colossus that can be approached from the surrounding public park.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Prairie Chicken', 'worlds-largest-prairie-chicken', 'roadside-oddities', 46.4814, -96.28161, 'Rothsay', 'MN', 'Rothsay''s enormous prairie chicken commemorates the bird and the grassland landscape surrounding the town. The statue is intentionally oversized and positioned as a quick roadside stop just off the main route.', 'roadside', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Loon', 'worlds-largest-loon', 'roadside-oddities', 46.66442, -95.79912, 'Vergas', 'MN', 'Minnesota''s state bird becomes a giant lakeside mascot in Vergas, where a huge loon stands in a public park. The sculpture is one of several outsized bird monuments scattered through western Minnesota.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Pelican Pete', 'pelican-pete', 'roadside-oddities', 46.571, -96.0827, 'Pelican Rapids', 'MN', 'Pelican Rapids built a concrete pelican on the river in the 1950s, creating a mascot that is far larger than any living bird. The riverside setting makes Pelican Pete more than a signboard curiosity and lets travelers walk right up to the landmark.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Big Fish', 'big-fish', 'roadside-oddities', 47.35165, -94.26667, 'Bena', 'MN', 'A massive muskie-shaped building survives beside U.S. Highway 2 in Bena, recalling an era when architecture itself was used to stop motorists. The fish is best appreciated from lawful public or business access rather than treated as an abandoned structure to enter.', 'roadside', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Crow', 'worlds-largest-crow', 'roadside-oddities', 45.44415, -95.0089, 'Belgrade', 'MN', 'A huge black crow watches over Belgrade from a landscaped public park. The bird turns the town''s Crow River connection into one of central Minnesota''s most straightforward giant-animal photo stops.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Erskine Giant Fish', 'erskine-giant-fish', 'roadside-oddities', 47.6666, -96.01112, 'Erskine', 'MN', 'A giant fish sculpture marks Erskine''s place in Minnesota''s long tradition of oversized lake-country mascots. Its simple public-facing setting makes it a quick detour rather than a ticketed attraction.', 'roadside', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Fishing Bobber Water Tower', 'fishing-bobber-water-tower', 'roadside-oddities', 46.60357, -94.31371, 'Pequot Lakes', 'MN', 'Pequot Lakes painted its spherical water tower like an enormous red-and-white fishing bobber. The working piece of municipal infrastructure doubles as a giant roadside object visible across town.', 'roadside', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Wally Walleye', 'wally-walleye', 'roadside-oddities', 46.29407, -93.8241, 'Garrison', 'MN', 'Garrison''s giant walleye stands beside Mille Lacs as a monument to the fishing culture that defines the community. The fish is positioned in a public lakeside area and has become one of the state''s better-known angling mascots.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Crosby Sea Serpent', 'crosby-sea-serpent', 'folklore', 46.47921, -93.95542, 'Crosby', 'MN', 'A fiberglass serpent called Kanabec coils beside Serpent Lake, turning the lake''s name into a physical monster. It is civic fantasy rather than a claimed cryptid specimen, but the creature gives OddWay a playful monster stop with a definite location.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Hockey Stick', 'worlds-largest-hockey-stick', 'roadside-oddities', 47.46132, -92.54013, 'Eveleth', 'MN', 'Eveleth''s giant hockey stick and puck celebrate a town deeply tied to the sport and the nearby U.S. Hockey Hall of Fame. The supersized equipment turns an ordinary downtown corner into a monumental sports object.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Iron Man', 'iron-man', 'roadside-oddities', 47.48138, -92.89581, 'Chisholm', 'MN', 'A towering miner rises above the Iron Range landscape as a memorial to the people who built the region''s mining industry. Its scale and industrial subject make it feel more like a colossus than a conventional civic statue.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Rocky Taconite', 'rocky-taconite', 'roadside-oddities', 47.29561, -91.26069, 'Silver Bay', 'MN', 'Silver Bay''s smiling taconite-pellet mascot transforms an industrial mining product into a giant cartoon character. Rocky is a concise, strange symbol of how completely iron mining shaped the North Shore community.', 'roadside', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Raspberry', 'worlds-largest-raspberry', 'roadside-oddities', 44.9255, -93.40997, 'Hopkins', 'MN', 'Hopkins commemorates its berry-growing past with an enormous raspberry in a downtown public space. The sculpture is an intentionally outsized reminder that the suburb was once closely associated with commercial raspberry production.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Mora Dala Horse', 'mora-dala-horse', 'roadside-oddities', 45.8692, -93.2971, 'Mora', 'MN', 'A giant Dala horse brings Scandinavian folk imagery to roadside scale in Mora. The brightly painted horse connects the community''s Swedish heritage to the same oversized-object tradition seen across rural Minnesota.', 'roadside', 'https://www.ci.mora.mn.us/community-development/pages/dala-horse', 'America/Chicago'),
  ('Corn Water Tower', 'corn-water-tower', 'roadside-oddities', 44.00544, -92.46017, 'Rochester', 'MN', 'A working water tower painted as an enormous ear of corn rises above Rochester''s skyline. The structure converts basic municipal infrastructure into a surreal agricultural landmark that can be seen from surrounding public roads.', 'roadside', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Lou T. Fisk', 'lou-t-fisk', 'roadside-oddities', 45.00818, -96.19599, 'Madison', 'MN', 'Madison''s giant lutefisk mascot gives a notoriously divisive Scandinavian-American food its own oversized monument. The fish named Lou T. Fisk is intentionally comic and makes the town''s cultural identity impossible to miss.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Sugar Beet', 'worlds-largest-sugar-beet', 'roadside-oddities', 47.35162, -96.82699, 'Halstad', 'MN', 'A giant sugar beet celebrates the crop and processing economy of the Red River Valley. The monument turns an ordinary root crop into a deliberately absurd roadside landmark at the edge of Halstad.', 'roadside', 'https://halstad.com/worlds-largest-sugar-beet/', 'America/Chicago'),
  ('World''s Largest Walleye', 'worlds-largest-walleye', 'roadside-oddities', 45.68402, -92.98781, 'Rush City', 'MN', 'An enormous walleye greets travelers in Rush City, one of several Minnesota towns that have made fishing culture literally larger than life. The sculpture is a simple, routeable roadside stop rather than an indoor attraction.', 'roadside', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('World''s Largest Boot', 'worlds-largest-boot', 'roadside-oddities', 44.5661, -92.53438, 'Red Wing', 'MN', 'Red Wing displays an enormous leather work boot tied to the city''s long shoemaking history. The giant footwear is indoors at the company''s flagship location, giving travelers an unusual industrial-brand artifact rather than another fiberglass animal.', 'open', 'https://www.redwingshoes.com/about-red-wing-shoes/', 'America/Chicago'),
  ('St. Urho Statue', 'st-urho-statue', 'folklore', 46.75004, -95.09543, 'Menahga', 'MN', 'Menahga honors St. Urho, a completely invented Finnish-American folk saint credited in comic legend with driving grasshoppers from Finland. The statue gives physical form to a modern piece of Upper Midwest ethnic folklore.', 'open', 'https://www.cityofmenahga.com/index.asp?SEC=895B71BD-EEBF-4E05-94D1-9508BCF6E9E4', 'America/Chicago'),
  ('Nyberg Sculpture Park', 'nyberg-sculpture-park', 'roadside-oddities', 46.26422, -95.53256, 'Vining', 'MN', 'Ken Nyberg transformed scrap metal into giant animals, tools and surreal mechanical forms scattered through this small-town park. The collection feels handmade and idiosyncratic rather than like standardized civic public art.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('The Calling — Giant Loon', 'the-calling-giant-loon', 'roadside-oddities', 44.95523, -93.16644, 'Saint Paul', 'MN', 'A monumental stainless-steel loon rises near the Minnesota United stadium, enlarging the state bird into a contemporary urban sculpture. Its scale and mirrorlike geometry make it a modern counterpoint to Minnesota''s older fiberglass roadside giants.', 'open', 'https://www.mnufc.com/stadium/art', 'America/Chicago'),
  ('Franconia Sculpture Park', 'franconia-sculpture-park', 'roadside-oddities', 45.38114, -92.70505, 'Shafer', 'MN', 'Dozens of large-scale sculptures occupy an open landscape where visitors can walk among works that range from playful to unsettling. The constantly changing outdoor collection rewards detours because it behaves more like an experimental art field than a formal gallery.', 'open', 'https://www.franconia.org/', 'America/Chicago'),
  ('Hot Sam''s Antiques & Foto Park', 'hot-sams-antiques-foto-park', 'roadside-oddities', 44.61837, -93.29491, 'Lakeville', 'MN', 'This private attraction mixes salvaged vehicles, eccentric sets, antique objects and staged photo environments into a deliberately strange landscape. Access depends on current hours and admission, so travelers should check before making the detour.', 'limited', 'https://www.hotsamsantiques.com/', 'America/Chicago'),
  ('R.W. Lindholm Service Station', 'rw-lindholm-service-station', 'roadside-oddities', 46.72139, -92.46083, 'Cloquet', 'MN', 'Frank Lloyd Wright designed this functioning service station as a small-scale expression of his Broadacre City ideas. The sharply cantilevered roof and observation lounge turn an everyday gas station into one of Minnesota''s strangest pieces of roadside modernism.', 'open', 'https://www.franklloydwrightsites.com/lindholm-service-station/', 'America/Chicago'),
  ('LARK Toys', 'lark-toys', 'museums', 44.30204, -92.00365, 'Kellogg', 'MN', 'A toy workshop, store, carousel and collection of vintage toys fill this sprawling stop in the Mississippi River valley. Its handmade wooden carousel and dense displays make it much more eccentric than a conventional toy shop.', 'open', 'https://larktoys.com/', 'America/Chicago'),
  ('Minnesota''s Largest Candy Store', 'minnesotas-largest-candy-store', 'roadside-oddities', 44.65393, -93.68494, 'Jordan', 'MN', 'A bright yellow barnlike building packs an overwhelming range of candy, soda and imported snacks into a seasonal roadside destination. The scale, color and deliberately excessive inventory make the store itself the attraction.', 'limited', 'https://minnesotaslargestcandystore.com/', 'America/Chicago'),
  ('Hermann the German Monument', 'hermann-the-german-monument', 'roadside-oddities', 44.30709, -94.47263, 'New Ulm', 'MN', 'A huge copper figure of Hermann the Cheruscan stands above New Ulm on a stone monument built by German-American fraternal groups. Seasonal tower access lets visitors climb beneath the statue while the grounds remain a striking exterior stop.', 'limited', 'https://www.newulmmn.gov/295/Hermann-Monument', 'America/Chicago'),
  ('Smokey Bear Statue', 'smokey-bear-statue', 'roadside-oddities', 48.60305, -93.40863, 'International Falls', 'MN', 'International Falls built a giant Smokey Bear as a public reminder of wildfire prevention in Minnesota''s north woods. The familiar campaign mascot becomes unexpectedly imposing when enlarged to roadside-monument scale.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Original Black Duck Statue', 'original-black-duck-statue', 'roadside-oddities', 47.73065, -94.54823, 'Blackduck', 'MN', 'Blackduck''s namesake bird appears as a large public statue near the center of town. It is a straightforward but distinctive example of a Minnesota community converting its literal name into a physical roadside mascot.', 'open', 'https://www.exploreminnesota.com/article/minnesotas-roadside-attractions-are-larger-than-life', 'America/Chicago'),
  ('Verne the Patriot — World''s Tallest Nutcracker', 'verne-the-patriot-worlds-tallest-nutcracker', 'roadside-oddities', 43.6419, -96.21373, 'Luverne', 'MN', 'Luverne unveiled the 65-foot-plus Verne the Patriot in July 2026, creating a working-jaw nutcracker promoted as the world''s tallest. The brand-new giant adds a contemporary record-chasing landmark to Minnesota''s long tradition of oversized roadside figures.', 'open', 'https://www.ap.org/news-highlights/spotlights/2026/a-minnesota-town-now-boasts-the-worlds-tallest-nutcracker/', 'America/Chicago'),
  ('Runestone Museum', 'runestone-museum', 'museums', 45.89021, -95.37808, 'Alexandria', 'MN', 'The museum displays the controversial Kensington Runestone, whose inscription claims a fourteenth-century Norse presence in Minnesota. Most professional runic scholars and historians regard the stone as a much later creation, making the artifact as interesting for the debate around it as for the carving itself.', 'limited', 'https://runestonemuseum.org/', 'America/Chicago'),
  ('Hjemkomst Center', 'hjemkomst-center', 'museums', 46.87787, -96.77828, 'Moorhead', 'MN', 'The center houses a full-scale Viking-style ship built in Minnesota and sailed to Norway, along with a replica Norwegian stave church. Both objects turn regional Scandinavian identity into unusually ambitious pieces of experimental heritage.', 'limited', 'https://www.hcscconline.org/', 'America/Chicago'),
  ('Judy Garland Museum', 'judy-garland-museum', 'museums', 47.2064, -93.52971, 'Grand Rapids', 'MN', 'Judy Garland''s childhood home is paired with a museum devoted to her life, career and The Wizard of Oz. The collection mixes Hollywood memorabilia with the intimate scale of the house where the future star spent her earliest years.', 'limited', 'https://judygarlandmuseum.com/', 'America/Chicago'),
  ('Greyhound Bus Museum', 'greyhound-bus-museum', 'weird-history', 47.4384, -92.93959, 'Hibbing', 'MN', 'Greyhound traces its roots to Hibbing, and this museum preserves buses, photographs and material from the company''s early years. Full-size coaches make the collection feel more like a transportation time capsule than a conventional local-history room.', 'limited', 'https://greyhoundbusmuseum.org/', 'America/Chicago'),
  ('Fagen Fighters WWII Museum', 'fagen-fighters-wwii-museum', 'weird-history', 44.75107, -95.55747, 'Granite Falls', 'MN', 'Restored World War II aircraft and vehicles fill a large private museum complex beside a working airfield. The machines are preserved at unusually high scale and detail, giving the site the atmosphere of a living wartime hangar.', 'limited', 'https://www.fagenfighterswwiimuseum.org/', 'America/Chicago'),
  ('Legacy of the Lakes Museum', 'legacy-of-the-lakes-museum', 'museums', 45.89027, -95.37935, 'Alexandria', 'MN', 'Historic wooden boats, outboard motors and lake-culture artifacts fill a museum devoted specifically to Minnesota''s recreational waters. The narrow collecting focus makes it an unusually concentrated record of how lake life shaped the state.', 'limited', 'https://legacyofthelakes.org/', 'America/Chicago'),
  ('Dorothy Molter Museum', 'dorothy-molter-museum', 'weird-history', 47.9028, -91.83378, 'Ely', 'MN', 'Dorothy Molter became known as the ''Root Beer Lady'' while living alone for decades in what became the Boundary Waters wilderness. Her relocated cabins and artifacts preserve the story of an unusually independent life that ended only after wilderness rules made her the final resident of the area.', 'limited', 'https://www.rootbeerlady.com/', 'America/Chicago'),
  ('International Wolf Center', 'international-wolf-center', 'museums', 47.90584, -91.8277, 'Ely', 'MN', 'Live ambassador wolves and detailed exhibits examine the biology, behavior and cultural mythology surrounding one of Minnesota''s most charged animals. The center provides factual context for the folklore and fear that often follow wolves through northern stories.', 'limited', 'https://wolf.org/', 'America/Chicago'),
  ('North American Bear Center', 'north-american-bear-center', 'museums', 47.89865, -91.88752, 'Ely', 'MN', 'The center combines live black bears with exhibits on bear behavior, research and popular misconceptions. It gives travelers a close look at an animal that appears constantly in North Woods folklore without presenting sensationalized encounter stories as fact.', 'limited', 'https://bear.org/', 'America/Chicago'),
  ('Bell Museum', 'bell-museum', 'museums', 44.99115, -93.18803, 'Falcon Heights', 'MN', 'Minnesota''s official natural-history museum combines wildlife dioramas, fossils and a planetarium under one roof. Its classic habitat displays preserve a museum style that can feel almost uncanny beside the building''s modern science exhibits.', 'limited', 'https://www.bellmuseum.umn.edu/', 'America/Chicago'),
  ('The Bakken Museum', 'the-bakken-museum', 'weird-history', 44.93824, -93.32112, 'Minneapolis', 'MN', 'This museum explores electricity, medical technology and invention inside an eccentric mansion on the shore of Bde Maka Ska. Displays on electrotherapy, early devices and Frankenstein-era ideas give the collection an unusually charged medical-science atmosphere.', 'limited', 'https://thebakken.org/', 'America/Chicago'),
  ('Pavek Museum', 'pavek-museum', 'museums', 44.93903, -93.34342, 'St. Louis Park', 'MN', 'Historic radios, televisions, broadcast equipment and recording technology trace how electronic media entered everyday life. Rows of obsolete machines make the museum a strong stop for travelers interested in technology that now looks stranger than it once did.', 'limited', 'https://pavekmuseum.org/', 'America/Chicago'),
  ('The Museum of Russian Art', 'the-museum-of-russian-art', 'roadside-oddities', 44.90343, -93.27594, 'Minneapolis', 'MN', 'A former church now houses a museum focused on Russian and Soviet-era art, an unusually specialized collection for the Upper Midwest. Rotating exhibitions can range from icons and folk art to Soviet realism and contemporary work.', 'limited', 'https://tmora.org/', 'America/Chicago'),
  ('American Swedish Institute', 'american-swedish-institute', 'roadside-oddities', 44.95498, -93.26595, 'Minneapolis', 'MN', 'The turreted Turnblad Mansion combines a lavish immigrant-era residence with a museum of Swedish and Swedish-American culture. Carved interiors, unusual fireplaces and the castlelike exterior make the building itself part of the OddWay draw.', 'limited', 'https://asimn.org/', 'America/Chicago'),
  ('Minnesota Transportation Museum', 'minnesota-transportation-museum', 'weird-history', 44.96252, -93.09597, 'Saint Paul', 'MN', 'The museum occupies the historic Jackson Street Roundhouse and preserves locomotives, railcars and transit equipment. Visitors can move through working railroad spaces rather than seeing transportation history reduced to small display cases.', 'limited', 'https://transportationmuseum.org/', 'America/Chicago'),
  ('Mill City Museum', 'mill-city-museum', 'weird-history', 44.97864, -93.25759, 'Minneapolis', 'MN', 'Built into the ruins of the Washburn A Mill, the museum interprets the flour industry that once made Minneapolis a milling capital. Exposed ruins and the building''s history of explosions and fire make the industrial setting as compelling as the exhibits.', 'limited', 'https://www.mnhs.org/millcity', 'America/Chicago'),
  ('Historic Fort Snelling', 'historic-fort-snelling', 'weird-history', 44.89305, -93.18574, 'Saint Paul', 'MN', 'The fort sits at a strategically and culturally significant confluence and carries intertwined military, Indigenous and settler histories. Modern interpretation addresses the Dakota homeland, slavery at the post and the site''s later military roles rather than presenting only a romantic frontier story.', 'limited', 'https://www.mnhs.org/fortsnelling', 'America/Chicago'),
  ('Split Rock Lighthouse', 'split-rock-lighthouse', 'weird-history', 47.20018, -91.36677, 'Two Harbors', 'MN', 'Built after deadly Lake Superior storms exposed the need for better navigation, Split Rock rises from a sheer North Shore cliff. The preserved light station combines engineering, shipwreck history and one of Minnesota''s most dramatic constructed landscapes.', 'limited', 'https://www.mnhs.org/splitrock/', 'America/Chicago'),
  ('Forest History Center', 'forest-history-center', 'weird-history', 47.22972, -93.56667, 'Grand Rapids', 'MN', 'A recreated logging camp and historic facilities interpret the dangerous, highly organized industry that transformed northern Minnesota forests. Living-history programs and heavy equipment give the site a physical scale missing from ordinary timber exhibits.', 'limited', 'https://www.mnhs.org/foresthistory', 'America/Chicago'),
  ('Snake River Fur Post', 'snake-river-fur-post', 'weird-history', 45.82305, -93.01423, 'Pine City', 'MN', 'A reconstructed North West Company fur post interprets the late-eighteenth-century trade network that linked Indigenous communities and European traders. The palisaded buildings make the economic and cultural frontier tangible without pretending the modern reconstruction is an untouched original.', 'limited', 'https://www.mnhs.org/furpost', 'America/Chicago'),
  ('Mille Lacs Indian Museum and Trading Post', 'mille-lacs-indian-museum-and-trading-post', 'weird-history', 46.17667, -93.75583, 'Onamia', 'MN', 'The museum presents Mille Lacs Band of Ojibwe history and contemporary culture alongside a historic trading post. Exhibits and community voices provide essential context for travelers encountering Ojibwe place names, stories and landscapes around central Minnesota.', 'limited', 'https://www.mnhs.org/millelacs', 'America/Chicago'),
  ('Jeffers Petroglyphs', 'jeffers-petroglyphs', 'weird-history', 44.09162, -95.05444, 'Comfrey', 'MN', 'Thousands of carvings made by Indigenous peoples cover exposed Sioux quartzite and remain culturally significant to descendant communities. Visit as a sacred archaeological landscape rather than a novelty, following staff guidance and staying within authorized areas.', 'limited', 'https://www.mnhs.org/jefferspetroglyphs', 'America/Chicago'),
  ('National Eagle Center', 'national-eagle-center', 'museums', 44.38444, -92.03131, 'Wabasha', 'MN', 'The Mississippi River valley draws large numbers of bald and golden eagles, and this center interprets their biology through exhibits and ambassador birds. Its location makes the museum directly connected to the wildlife phenomenon outside its doors.', 'limited', 'https://www.nationaleaglecenter.org/', 'America/Chicago'),
  ('Lake Superior Railroad Museum', 'lake-superior-railroad-museum', 'weird-history', 46.78104, -92.10403, 'Duluth', 'MN', 'Historic locomotives and railcars fill Duluth''s monumental Union Depot, including equipment tied to the iron and timber economies of the region. The scale of the trains and station turns a transportation collection into an immersive industrial stop.', 'limited', 'https://lsrm.org/', 'America/Chicago'),
  ('Chik-Wauk Museum and Nature Center', 'chik-wauk-museum-and-nature-center', 'museums', 48.16871, -90.88085, 'Grand Marais', 'MN', 'At the end of the Gunflint Trail, Chik-Wauk interprets a remote landscape shaped by Indigenous travel, resorts, logging and wilderness tourism. The isolated setting makes the journey part of the experience rather than simply a museum visit.', 'limited', 'https://www.chikwauk.com/', 'America/Chicago'),
  ('SPAM Museum', 'spam-museum', 'museums', 43.66945, -92.97441, 'Austin', 'MN', 'Hormel turned one of America''s most recognizable canned foods into a full museum of advertising, production history and pop culture. The free attraction treats SPAM with enough seriousness and humor to make a single processed meat the subject of an entire destination.', 'open', 'https://www.spam.com/museum', 'America/Chicago'),
  ('U.S. Hockey Hall of Fame Museum', 'us-hockey-hall-of-fame-museum', 'museums', 47.47144, -92.52856, 'Eveleth', 'MN', 'Eveleth''s museum preserves the history of American hockey through trophies, equipment and stories from players at every level. Its location on the Iron Range makes the collection inseparable from a region that produced an outsized share of the sport''s history.', 'limited', 'https://www.ushockeyhall.com/', 'America/Chicago'),
  ('Owatonna State School Orphanage Museum', 'owatonna-state-school-orphanage-museum', 'weird-history', 44.08969, -93.22077, 'Owatonna', 'MN', 'The former Minnesota State Public School for Dependent and Neglected Children preserves buildings, records and first-person stories from thousands of children who lived here. The museum treats institutional childhood and its difficult history through documented testimony rather than ghost-story sensationalism.', 'limited', 'https://www.orphanagemuseum.com/', 'America/Chicago'),
  ('Dassel History Center & Ergot Museum', 'dassel-history-center-ergot-museum', 'weird-history', 45.08625, -94.30792, 'Dassel', 'MN', 'A local history center contains an unusually specific museum devoted to ergot, the fungus once cultivated and processed around Dassel for pharmaceutical use. The subject links agriculture, toxicology and medicine in a way few small-town museums attempt.', 'limited', 'https://dassel.com/dassel-history-center-and-ergot-museum', 'America/Chicago'),
  ('W. W. Mayo House', 'w-w-mayo-house', 'weird-history', 44.46216, -93.91516, 'Le Sueur', 'MN', 'Dr. W. W. Mayo built this modest house and used it for his early medical practice before his family became synonymous with the Mayo Clinic. The same home later belonged to the Cosgrove family of Green Giant fame, tying two major Minnesota legacies to one small building.', 'limited', 'https://www.mnhs.org/mayohouse', 'America/Chicago'),
  ('Twin City Model Railroad Museum', 'twin-city-model-railroad-museum', 'museums', 44.96084, -93.18556, 'Saint Paul', 'MN', 'A sprawling model railroad recreates towns, industries and transportation scenes in miniature, with trains circulating through dense hand-built landscapes. The obsessive scale and mechanical detail make it a strong niche-museum stop rather than a generic train display.', 'limited', 'https://www.tcmrm.org/', 'America/Chicago'),
  ('Minnesota Discovery Center', 'minnesota-discovery-center', 'weird-history', 47.47806, -92.89611, 'Chisholm', 'MN', 'This large Iron Range complex combines mining history, immigrant stories, archives and outdoor industrial artifacts. The setting helps explain why so many enormous pits, machines and mining monuments dominate the surrounding landscape.', 'limited', 'https://www.mndiscoverycenter.org/', 'America/Chicago'),
  ('Great Hinckley Fire Museum', 'great-hinckley-fire-museum', 'weird-history', 46.015, -92.94333, 'Hinckley', 'MN', 'A restored railroad depot tells the story of the catastrophic 1894 Hinckley fire through artifacts, photographs and survivor accounts. The museum is seasonal, so current hours matter if the fire history is the reason for the detour.', 'limited', 'https://hinckleyfiremuseum.com/', 'America/Chicago'),
  ('Val Johnson UFO Car — Marshall County Historical Society', 'val-johnson-ufo-car-marshall-county-historical-society', 'ufos', 48.2002, -96.7596, 'Warren', 'MN', 'Marshall County preserves the damaged patrol car from Deputy Val Johnson''s reported 1979 encounter with a strange light. The bent antennas and cracked windshield are real artifacts; an extraterrestrial explanation remains an unresolved claim rather than established fact.', 'limited', 'https://www.mchistoricalsociety.com/exhibit', 'America/Chicago'),
  ('Charles Lindbergh House and Museum', 'charles-lindbergh-house-and-museum', 'weird-history', 45.95804, -94.38786, 'Little Falls', 'MN', 'The childhood home of aviator Charles Lindbergh sits beside the Mississippi with exhibits on his early life and famous transatlantic flight. Interpretation also addresses the more difficult and controversial parts of Lindbergh''s later public life.', 'limited', 'https://www.mnhs.org/lindbergh', 'America/Chicago'),
  ('Oliver Kelley Farm', 'oliver-kelley-farm', 'weird-history', 45.25968, -93.53999, 'Elk River', 'MN', 'This working historic farm interprets nineteenth-century agriculture on the former property of Grange founder Oliver H. Kelley. Costumed programs, livestock and historic buildings turn agricultural history into a physical landscape rather than a static display.', 'limited', 'https://www.mnhs.org/kelleyfarm', 'America/Chicago'),
  ('Harkin Store', 'harkin-store', 'weird-history', 44.38696, -94.59918, 'New Ulm', 'MN', 'A preserved 1870s general store stands where a river town once expected the railroad to bring prosperity before the line bypassed it. The building is currently closed to normal interior visitation, but the historic grounds remain a tangible remnant of a community left behind.', 'roadside', 'https://www.mnhs.org/harkinstore', 'America/Chicago'),
  ('Niagara Cave', 'niagara-cave', 'roadside-oddities', 43.51396, -92.05507, 'Harmony', 'MN', 'Guided tours descend into a limestone cave containing narrow passages, fossils, formations and an underground waterfall. The vertical route gives southern Minnesota a substantial subterranean stop far removed from the flat farmland above.', 'limited', 'https://niagaracave.com/', 'America/Chicago'),
  ('Mystery Cave', 'mystery-cave', 'roadside-oddities', 43.61729, -92.31183, 'Preston', 'MN', 'Minnesota''s longest known cave winds beneath Forestville/Mystery Cave State Park through passages shaped by groundwater in limestone. DNR-guided tours are seasonal and route-specific, so travelers should reserve rather than treating it as an open cavern.', 'limited', 'https://www.dnr.state.mn.us/state_parks/tours/mystery_cave.html', 'America/Chicago'),
  ('Soudan Underground Mine', 'soudan-underground-mine', 'weird-history', 47.82306, -92.23694, 'Soudan', 'MN', 'Visitors descend deep underground into a former Iron Range mine on a guided state-park tour. The cages, tunnels and machinery make the industrial scale tangible, and 2026 tours have resumed after a long closure for rehabilitation.', 'limited', 'https://www.dnr.state.mn.us/state_parks/tours/lake_vermilion_soudan.html', 'America/Chicago'),
  ('Devil''s Kettle', 'devils-kettle', 'roadside-oddities', 47.82922, -90.04952, 'Grand Marais', 'MN', 'The Brule River splits around a rock outcrop, with one branch plunging into a deep pothole long rumored to swallow the water without an outlet. Hydrologic measurements indicate the water rejoins the river downstream, but the strange geometry still gives the falls its enduring mystery.', 'limited', 'https://www.dnr.state.mn.us/mcvmagazine/issues/2017/mar-apr/devils-kettle-mystery.html', 'America/Chicago'),
  ('Magnetic Rock Trail', 'magnetic-rock-trail', 'roadside-oddities', 48.09189, -90.82541, 'Grand Marais', 'MN', 'A large iron-rich rock near the end of this Gunflint Trail hike can noticeably affect a compass. The phenomenon is geological rather than paranormal, but the isolated boulder gives travelers a simple physical experiment in the middle of the forest.', 'limited', 'https://www.fs.usda.gov/superior', 'America/Chicago'),
  ('Quarry Park & Nature Preserve', 'quarry-park-nature-preserve', 'weird-history', 45.53666, -94.24211, 'Waite Park', 'MN', 'Abandoned granite quarries, derricks and stoneworking remnants have been converted into a public recreation landscape. Deep water-filled pits and surviving industrial equipment make the park feel like a reclaimed extraction site rather than an ordinary green space.', 'open', 'https://www.stearnscountymn.gov/396/Quarry-Park-Nature-Preserve', 'America/Chicago'),
  ('Big Bog Boardwalk', 'big-bog-boardwalk', 'roadside-oddities', 48.28648, -94.55378, 'Waskish', 'MN', 'A long boardwalk carries visitors directly into one of the largest peatland systems in the Lower 48 without requiring them to wade through the bog. Carnivorous plants, orchids and floating-looking ground make the environment feel unlike most Minnesota parks.', 'open', 'https://www.dnr.state.mn.us/state_parks/park.html?id=spk00175', 'America/Chicago'),
  ('Kettle Falls Hotel', 'kettle-falls-hotel', 'weird-history', 48.50294, -92.63991, 'Kabetogama', 'MN', 'This remote historic hotel sits inside Voyageurs National Park and can be reached only by water, trail or aircraft rather than by ordinary road. Its isolation, old border-country history and famously uneven saloon floor make arrival itself part of the OddWay experience.', 'limited', 'https://www.kettlefallshotel.com/directions', 'America/Chicago'),
  ('Hull Rust Mine View', 'hull-rust-mine-view', 'weird-history', 47.44667, -92.94306, 'Hibbing', 'MN', 'An overlook faces the enormous open-pit iron mine landscape that reshaped Hibbing and forced part of the original city to move. The scale is difficult to grasp from maps alone, making the lawful overlook a better stop than attempting to approach active mining areas.', 'open', 'https://www.hibbingmn.gov/276/Hull-Rust-Mine-View---North-Hibbing', 'America/Chicago'),
  ('Blue Mounds State Park Bison Range', 'blue-mounds-state-park-bison-range', 'museums', 43.71694, -96.18889, 'Luverne', 'MN', 'A conservation herd of bison occupies native prairie above dramatic Sioux quartzite cliffs. Seasonal guided programs can bring visitors closer to the herd, while normal park access still offers a broader view of the prairie ecosystem.', 'limited', 'https://www.dnr.state.mn.us/state_parks/tours/prairie-and-bison.html', 'America/Chicago'),
  ('Pipestone National Monument', 'pipestone-national-monument', 'weird-history', 44.01352, -96.32476, 'Pipestone', 'MN', 'For generations, Indigenous peoples have quarried the soft red stone here for ceremonial pipes and continue to do so under protected traditions. The site should be visited as a living sacred cultural landscape, not merely as an unusual geological quarry.', 'open', 'https://www.nps.gov/pipe/', 'America/Chicago'),
  ('Grand Portage National Monument', 'grand-portage-national-monument', 'weird-history', 47.99294, -89.75573, 'Grand Portage', 'MN', 'The monument preserves a critical Lake Superior trade corridor and interprets the intertwined histories of the Grand Portage Ojibwe and the North West Company fur trade. Reconstructed buildings and the historic carrying route give physical form to a transportation system older than modern roads.', 'open', 'https://www.nps.gov/grpo/', 'America/Chicago'),
  ('Aerial Lift Bridge', 'aerial-lift-bridge', 'roadside-oddities', 46.779, -92.0928, 'Duluth', 'MN', 'Duluth''s harbor bridge rises vertically to let large ships pass through the canal between Lake Superior and the inner harbor. Watching the roadway lift for a freighter turns working transportation infrastructure into a public mechanical performance.', 'open', 'https://visitduluth.com/experience/signature-sights/aerial-lift-bridge/', 'America/Chicago'),
  ('S.S. William A. Irvin', 'ss-william-a-irvin', 'weird-history', 46.77943, -92.09881, 'Duluth', 'MN', 'A retired Great Lakes ore carrier is permanently moored in Duluth and opened seasonally for tours through crew spaces and cargo areas. The ship translates the scale of iron-ore shipping into tight corridors, machinery and enormous holds visitors can actually enter.', 'limited', 'https://decc.org/william-a-irvin/', 'America/Chicago'),
  ('Enger Tower', 'enger-tower', 'roadside-oddities', 46.77611, -92.12461, 'Duluth', 'MN', 'A five-story stone observation tower rises from a hill above Duluth, built in the 1930s and crowned with a beacon. The vertical climb and panoramic harbor view make it a compact piece of civic architecture with an almost castlelike silhouette.', 'open', 'https://duluthmn.gov/parks/parks-listing/enger-park/', 'America/Chicago'),
  ('Witch''s Hat Water Tower', 'witchs-hat-water-tower', 'roadside-oddities', 44.96892, -93.21274, 'Minneapolis', 'MN', 'The 1914 Prospect Park water tower is capped by a steep green-tile roof that gave it the nickname Witch''s Hat. The surrounding park is public, but the tower interior is normally closed and traditionally opens only for a rare neighborhood event.', 'roadside', 'https://www.minneapolisparks.org/parks-destinations/parks-lakes/tower_hill_park/', 'America/Chicago'),
  ('Mississippi Headwaters', 'mississippi-headwaters', 'roadside-oddities', 47.23988, -95.20781, 'Lake Itasca', 'MN', 'At Lake Itasca, visitors can walk across the shallow outlet traditionally designated as the headwaters of the Mississippi River. The modest stream is visually strange when compared with the enormous river it becomes downstream.', 'open', 'https://www.dnr.state.mn.us/state_parks/park.html?id=spk00181', 'America/Chicago'),
  ('Lost Forty', 'lost-forty', 'roadside-oddities', 47.76617, -94.08442, 'Northome', 'MN', 'A surveying error helped spare this tract of old-growth pine from the logging that transformed much of northern Minnesota. Trails now pass among trees that survive partly because nineteenth-century mapmakers put the land in the wrong place.', 'open', 'https://www.exploreminnesota.com/profile/lost-40-sna/5508', 'America/Chicago'),
  ('Interstate State Park Glacial Potholes', 'interstate-state-park-glacial-potholes', 'roadside-oddities', 45.39999, -92.65117, 'Taylors Falls', 'MN', 'Powerful meltwater drilled enormous cylindrical potholes into basalt along the St. Croix River. A concentrated cluster beside the park''s trails lets visitors stand among some of the deepest and most dramatic glacial potholes in the region.', 'open', 'https://www.dnr.state.mn.us/state_parks/virtual_tour/interstate/dialup.html', 'America/Chicago'),
  ('High Falls — Grand Portage State Park', 'high-falls-grand-portage-state-park', 'roadside-oddities', 48.00491, -89.59794, 'Grand Portage', 'MN', 'The Pigeon River drops roughly 120 feet at High Falls on the U.S.–Canada boundary, making it Minnesota''s highest waterfall. A public trail and boardwalk approach the falls without requiring travelers to cross the international border.', 'open', 'https://www.dnr.state.mn.us/state_parks/grand_portage/things_to_do.html', 'America/Chicago'),
  ('Palisade Head', 'palisade-head', 'roadside-oddities', 47.31936, -91.21627, 'Silver Bay', 'MN', 'A massive volcanic cliff rises directly above Lake Superior and can be reached by a steep seasonal access road and short walk. The exposed height and columnlike rock make this one of the North Shore''s most dramatic geological stops.', 'limited', 'https://www.dnr.state.mn.us/state_parks/park.html?id=spk00269', 'America/Chicago'),
  ('Minnesota Point Lighthouse Ruins', 'minnesota-point-lighthouse-ruins', 'weird-history', 46.71013, -92.02589, 'Duluth', 'MN', 'The ruins of Minnesota''s first lighthouse stand near the end of the long Park Point sandbar after a hike through dunes and woods. The surviving tower is not an interior attraction, so travelers should observe it from the trail and respect barriers around the structure.', 'roadside', 'https://visitduluth.com/experience/signature-sights/park-point/', 'America/Chicago'),
  ('Two Harbors Lighthouse', 'two-harbors-lighthouse', 'weird-history', 47.014, -91.6635, 'Two Harbors', 'MN', 'Minnesota''s oldest continuously operated lighthouse occupies a rocky point above Agate Bay. Museum access and the possibility of staying in the keeper''s quarters make the working light station more immersive than a simple shoreline viewpoint.', 'limited', 'https://www.lakecountyhistoricalsociety.org/', 'America/Chicago'),
  ('Rabideau CCC Camp', 'rabideau-ccc-camp', 'weird-history', 47.63999, -94.54862, 'Blackduck', 'MN', 'One of the country''s best-preserved Civilian Conservation Corps camps survives in the Chippewa National Forest with original buildings and landscape features. The remote complex feels like a preserved government work camp rather than a reconstructed museum village.', 'limited', 'https://www.fs.usda.gov/chippewa', 'America/Chicago'),
  ('Palmer House Hotel', 'palmer-house-hotel', 'haunted', 45.73739, -94.95229, 'Sauk Centre', 'MN', 'This operating historic hotel has built a strong reputation around reports of apparitions, unexplained sounds and other alleged activity. Guests can lawfully experience the building through normal lodging and scheduled programming rather than trespassing in an abandoned property.', 'limited', 'https://www.thepalmerhousehotel.com/', 'America/Chicago'),
  ('Wabasha Street Caves', 'wabasha-street-caves', 'weird-history', 44.93579, -93.08702, 'Saint Paul', 'MN', 'Man-made sandstone caves beneath Saint Paul have served different uses over time, including commercial mushroom growing and entertainment spaces associated with the Prohibition era. Guided tours interpret the caves'' history and legends without encouraging unsupervised entry into underground spaces.', 'limited', 'https://www.wabashastreetcaves.com/', 'America/Chicago'),
  ('Glensheen Mansion', 'glensheen-mansion', 'weird-history', 46.81516, -92.05174, 'Duluth', 'MN', 'This immense Jacobean Revival estate preserves the world of a wealthy mining and legal family on Lake Superior. Its architectural grandeur is inseparable in popular memory from the 1977 murders of Elisabeth Congdon and her nurse, a real crime that should be treated as documented history rather than paranormal spectacle.', 'limited', 'https://glensheen.org/', 'America/Chicago'),
  ('Kensington Rune Stone Park — Discovery Site', 'kensington-rune-stone-park-discovery-site', 'weird-history', 45.81273, -95.67033, 'Kensington', 'MN', 'This county park preserves the Ohman farm landscape where Olof Ohman said he discovered the Kensington Runestone in 1898. A modern display interprets the find at the original site, while Minnesota''s state archaeologist notes that most professional scholars consider the stone a late-nineteenth-century creation rather than medieval evidence.', 'open', 'https://www.douglascountymn.gov/kensington-runestone-park', 'America/Chicago'),
  ('Mounds Theatre', 'mounds-theatre', 'haunted', 44.95249, -93.05696, 'Saint Paul', 'MN', 'A restored neighborhood theater hosts performances and has also publicized long-running reports of unexplained activity inside the building. Any ghost claims should be treated as local lore, while access remains through authorized events and scheduled programs.', 'limited', 'https://moundstheatre.org/', 'America/Chicago'),
  ('St. James Hotel — Red Wing', 'st-james-hotel-red-wing', 'haunted', 44.56589, -92.53594, 'Red Wing', 'MN', 'The 1875 hotel remains in operation and has accumulated stories of apparitions and unusual activity over its long history. Staying, dining or attending authorized events offers a lawful way to experience the atmospheric building without treating the folklore as verified fact.', 'limited', 'https://st-james-hotel.com/', 'America/Chicago'),
  ('Grasshopper Chapel', 'grasshopper-chapel', 'weird-history', 45.45614, -94.41385, 'Cold Spring', 'MN', 'This small hilltop chapel commemorates the region''s devastating nineteenth-century grasshopper plagues and the community''s religious response to them. The current granite chapel preserves an unusual intersection of agricultural disaster, local memory and pilgrimage.', 'limited', 'https://christcatholic.com/parishes/assumption-chapel/', 'America/Chicago'),
  ('Milford Mine Memorial Park', 'milford-mine-memorial-park', 'weird-history', 46.53407, -93.97053, 'Crosby', 'MN', 'The park preserves the landscape of the 1924 Milford Mine disaster, one of Minnesota''s deadliest mining accidents. Trails, interpretive material and surviving features let visitors encounter the site itself rather than only reading about the event in a museum.', 'open', 'https://crowwing.gov/294/Milford-Mine-Memorial-Park', 'America/Chicago'),
  ('Pepie — Lake Pepin Monster Viewpoint', 'pepie-lake-pepin-monster-viewpoint', 'cryptids', 44.45222, -92.26611, 'Lake City', 'MN', 'Lake Pepin has accumulated stories of a large unidentified creature nicknamed Pepie, a regional lake-monster tradition promoted by the surrounding community. The public shoreline viewpoint gives OddWay a safe place to engage with the legend without implying that a cryptid has been scientifically confirmed.', 'open', 'https://www.visitlakecity.org/pepie-the-lake-pepin-monster/', 'America/Chicago'),
  ('House of Balls', 'house-of-balls', 'roadside-oddities', 44.9684, -93.25127, 'Minneapolis', 'MN', 'Artist Allen Christian transformed a former industrial workspace into an evolving environment of carved bowling balls, found objects and strange humanlike figures. Access can be irregular, so travelers should confirm current visiting options instead of assuming the studio is always open.', 'limited', 'http://houseofballs.com/', 'America/Chicago'),
  ('Smallest Museum in St. Paul', 'smallest-museum-in-st-paul', 'museums', 44.96434, -93.19802, 'Saint Paul', 'MN', 'A tiny display case built into a former fire-hose cabinet functions as a street-facing museum only a few feet across. Rotating exhibits turn an ordinary exterior wall at Workhorse Coffee into a genuinely miniature year-round cultural stop.', 'open', 'https://www.smallestmuseumstpaul.com/about-the-smsp', 'America/Chicago'),
  ('Lakewood Cemetery Memorial Chapel', 'lakewood-cemetery-memorial-chapel', 'roadside-oddities', 44.93608, -93.29914, 'Minneapolis', 'MN', 'An ornate Byzantine-inspired chapel glitters with millions of mosaic pieces inside Lakewood Cemetery. Visitors should treat both the chapel and surrounding graves as active memorial spaces, checking cemetery access and any current chapel hours before entering.', 'limited', 'https://www.lakewoodcemetery.org/', 'America/Chicago'),
  ('James J. Hill House', 'james-j-hill-house', 'roadside-oddities', 44.945, -93.10889, 'Saint Paul', 'MN', 'Railroad magnate James J. Hill''s enormous Richardsonian Romanesque mansion contains heavy stonework, complex mechanical systems and extravagantly scaled rooms. Guided access reveals the infrastructure behind a Gilded Age home built almost like a private institution.', 'limited', 'https://www.mnhs.org/hillhouse', 'America/Chicago'),
  ('Peavey-Haglin Experimental Concrete Grain Elevator', 'peavey-haglin-experimental-concrete-grain-elevator', 'roadside-oddities', 44.9424, -93.3452, 'St. Louis Park', 'MN', 'This slender 1899–1900 concrete cylinder was an engineering experiment that proved circular reinforced-concrete grain elevators could work. It became a prototype for a form that would eventually define grain-handling landscapes across North America; view the structure from lawful public areas.', 'roadside', 'https://www.loc.gov/item/mn0125/', 'America/Chicago'),
  ('New Ulm Glockenspiel', 'new-ulm-glockenspiel', 'roadside-oddities', 44.31701, -94.46268, 'New Ulm', 'MN', 'A freestanding downtown clock tower contains bells and animated figures that perform scheduled scenes tied to New Ulm''s German heritage. The mechanism turns a public plaza into a miniature automaton theater several times a day.', 'open', 'https://www.newulmmn.gov/', 'America/Chicago'),
  ('Foshay Museum & Observation Deck', 'foshay-museum-observation-deck', 'roadside-oddities', 44.97456, -93.27157, 'Minneapolis', 'MN', 'The Art Deco Foshay Tower contains a small museum about utilities magnate Wilbur Foshay and an outdoor observation deck high above downtown. Foshay''s spectacular rise and fraud conviction add an unusually dramatic human story to the skyscraper''s architecture.', 'limited', 'https://www.marriott.com/en-us/hotels/mspwh-w-minneapolis-the-foshay/experiences/', 'America/Chicago')
on conflict (slug) do update set
  name          = excluded.name,
  category      = excluded.category,
  city          = excluded.city,
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  timezone      = excluded.timezone;
